import fs from'node:fs';import cp from'node:child_process';import path from'node:path';import assert from'node:assert/strict';import{createHash}from'node:crypto';
const [root,out]=process.argv.slice(2),commit='7351816ce8cfecd29fcf7dbdffbee60ca46c1791',base='docs/healthroster-build/proposals/paid-match-legacy-current-viewer-consumer-20261015/',sha=b=>createHash('sha256').update(b).digest('hex');
const blob=(rev,p)=>cp.execFileSync('git',['cat-file','blob',rev+':'+p],{cwd:root,maxBuffer:8e6});
function seal(){const b=blob(commit,base+'FROZEN_ARTIFACT_MANIFEST.json'),m=JSON.parse(b);for(const e of [...m.artifacts,{file:'FROZEN_ARTIFACT_MANIFEST.json'}]){const b=blob(commit,base+e.file);assert.deepEqual(b,fs.readFileSync(path.join(root,base+e.file)));if(e.sha256){assert.equal(b.length,e.bytes);assert.equal(sha(b),e.sha256);}}return{artifacts:m.artifacts.length+1,manifest_sha256:sha(b)};}
const before=seal(),p=JSON.parse(blob(commit,base+'COMPLETE_REVERSE_AND_INPUT_PINS.json'));let s=blob(commit,base+'forward/01_complete_choice_current.sqlinc').toString();assert.equal(sha(s),p.after_sha256);assert.equal(p.hunks.length,2);for(const h of [...p.hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);}assert.deepEqual(Buffer.from(s),blob(p.commit,p.source));
fs.mkdirSync(out,{recursive:true});const r=cp.spawnSync(process.execPath,['--test','--test-reporter=tap',base+'viewer-source.test.mjs'],{cwd:root,encoding:'utf8',maxBuffer:8e6});const output=Buffer.from(r.stdout+r.stderr);fs.writeFileSync(path.join(out,'SOURCE_TEST_OUTPUT.txt'),output);assert.equal(r.status,0);assert.match(output.toString(),/# pass 18\b/);assert.match(output.toString(),/# fail 0\b/);
const c={source_only:true,native:false,mount_ready:false,commit,before,after:seal(),source_cases:18,whole_owners:1,unique_hunks:2,output_sha256:sha(output),original_confirmation_immutable:true,actual_current_viewer_authority_preserved:true,literal_legacy_reader_actor_fields_only:true,native_financial_classification_unchanged:true,compiled_contract_native_full_acceptance:false};fs.writeFileSync(path.join(out,'CHECKS.json'),JSON.stringify(c,null,2)+'\n');console.log(JSON.stringify(c));
